export const NODI_CHAT_PROMPT_PACKS: Record<PromptLanguage, NodiChatPromptPack> = {
  es: SPANISH,
  en: ENGLISH,
  fr: FRENCH,
  de: GERMAN,
  pt: EUROPEAN_PORTUGUESE,
  'pt-BR': BRAZILIAN_PORTUGUESE,
  it: ITALIAN,
  tr: TURKISH,
};

export function getNodiChatPromptPack(language: string | undefined): NodiChatPromptPack {
  return NODI_CHAT_PROMPT_PACKS[language as PromptLanguage] ?? NODI_CHAT_PROMPT_PACKS.es;
}
